const $ = s => document.querySelector(s);
const escape = value => String(value ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let dashboard='Manufacturing',identity=null,partSort={key:'name',direction:'asc'};
let accessRole='viewer';let workspace,activeProject='robot-1',isAdmin=false,shared=null;
let state, view='parts', editing=null, toastTimer;
let shopMode=false, wakeLock=null, keepAwake=false, previousView='parts';
let pendingStart=null,workPart=null,workOriginal='';
try { const saved=localStorage.getItem(STORAGE_KEY); state=saved ? JSON.parse(saved):emptyWorkspace(); if(!validWorkspace(state)) throw new Error('Invalid workspace'); state=normalizeAssignments(state); }
catch { state={version:1,parts:[],materials:[],cots:[],demo:false}; $('#save-status').textContent='Saved data could not be read. Restore a backup to recover your records.'; }
workspace=normalizeProjects(state);try{activeProject=localStorage.getItem('frc7028-active-project')||activeProject;}catch{}if(!workspace.projects.some(p=>p.id===activeProject&&!p.archived))activeProject=workspace.projects.find(p=>!p.archived).id;state=projectScope(workspace,activeProject);
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4000);}
function loadShared(next){workspace=normalizeAssignments(next);if(workspace.importState?.lastSuccess)$('#onshape-last-sync').textContent='Last confirmed import: '+new Date(workspace.importState.lastSuccess).toLocaleString();if(!workspace.projects.some(p=>p.id===activeProject&&!p.archived))activeProject=workspace.projects.find(p=>!p.archived).id;state=projectScope(workspace,activeProject);localStorage.setItem(STORAGE_KEY,JSON.stringify(workspace));refreshFilters();refreshProjectPicker();render();$('.local-note').textContent='Shared team workspace';}
function saveWorkspace(next,restore=false){if(!shared?.ready){toast('Editing unavailable. Check the sync status and retry or resolve the pending save.');return false;}if(!validWorkspace(next)){toast('Check project names and part data.');return false;}if(!shared.save(next,{restore}))return false;workspace=next;state=projectScope(workspace,activeProject);localStorage.setItem(STORAGE_KEY,JSON.stringify(workspace));$('#save-status').textContent='Syncing with team';return true;}
function save(next){return saveWorkspace(mergeProject(workspace,next,activeProject));}
function refreshProjectPicker(){const options=workspace.projects.filter(p=>!p.archived).map(p=>'<option value="'+escape(p.id)+'">'+escape(p.name)+' · '+p.year+'</option>').join('')+(isAdmin?'<option value="__new__">New Project</option>':'');for(const id of ['project-picker','shop-project-picker']){const el=$('#'+id);el.innerHTML=options;el.value=activeProject;}}
function chooseProject(id){if(document.querySelector('dialog[open]'))return;if(!workspace.projects.some(p=>p.id===id&&!p.archived))return;activeProject=id;try{localStorage.setItem('frc7028-active-project',id);}catch{}state=projectScope(workspace,id);refreshProjectPicker();refreshFilters();switchView(view);}
function cleanSavedWorkspace(workspace){
 const result=cleanWorkspace(workspace);if(!result.changed)return workspace;
 try{const key=STORAGE_KEY+'-before-cleanup-v1';if(!localStorage.getItem(key))localStorage.setItem(key,JSON.stringify(workspace));localStorage.setItem(STORAGE_KEY,JSON.stringify(result.workspace));return result.workspace;}
 catch{toast('Cleanup could not be backed up. Your original records were kept.');return workspace;}
}
function today(){return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Chicago',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
const overdue = p => overdueDays(p)>0;
const dateLabel=d=>d?new Date(d+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric'}):'No deadline';
function baseFiltered(){const term=$('#search').value.trim().toLowerCase();const rows=view==='cots'?state.cots:state.parts;return rows.filter(r=>Object.values(r).join(' ').toLowerCase().includes(term)&&(!$('#subsystem-filter').value||(view==='cots'?vendorName(r.vendor):r.subsystem)===$('#subsystem-filter').value)&&(view!=='cots'||!$('#status-filter').value||cotsStatus(r)===$('#status-filter').value));}
function render(){
 $('#onshape-target').textContent='BOM destination: '+(workspace.projects.find(p=>p.id===workspace.onshapeProjectId)?.name||'Disconnected');
 const manufacturing=dashboard==='Manufacturing';$('nav').hidden=!manufacturing;$('.header-actions').hidden=!manufacturing;$('.shop-controls').hidden=!manufacturing||!shopMode;
 $('#admin-tools').hidden=!manufacturing||view!=='admin'||!isAdmin;
 if(!manufacturing){specialView(dashboard);$('#special-panel').innerHTML='<section class="construction"><span class="construction-mark" aria-hidden="true">⌁</span><h1>'+escape(dashboard)+'</h1><p>Under construction</p></section>';return;}
 if(view==='admin'){renderAdmin();return;}
 if(view==='todo'){specialView('Todo');$('#special-panel').innerHTML=todoTable(workspace,identity);return;}
 $('#special-panel').hidden=true;$('.content-panel').hidden=false;
 $('#add-record').hidden=!isAdmin||view==='board';$('#add-record').textContent=view==='cots'?'Add COTS Part':'Add part';
 $('#board-summary').hidden=view!=='board';if(view==='board')$('#board-summary').innerHTML=productionDashboard(state.parts);
 $('#vendor-orders').hidden=view!=='cots'||!state.cots.length;$('#vendor-orders').innerHTML=view==='cots'?vendorOrders(state.cots):'';
 const rows=filtered();$('#result-count').textContent=`Showing ${rows.length} of ${view==='cots'?state.cots.length:state.parts.length} ${view==='cots'?'COTS parts':'parts'}`;
 if(view==='board'){$('#records').innerHTML=shopBoard(rows,dateLabel,{isAdmin});return;}
 if(view==='cots'){$('#records').innerHTML=rows.length?cotsTable(rows):cotsEmptyState(state.cots.length);return;}
 $('#records').innerHTML=rows.length?partsRegister(rows,partSort):emptyResults();
}
function refreshFilters(){const old=$('#subsystem-filter').value,status=$('#status-filter').value;const cots=view==='cots';$('#status-filter').innerHTML='<option value="">'+(cots?'All statuses':'All stages')+'</option>'+(cots?COTS_STATUSES:STATUSES).map(s=>'<option>'+s+'</option>').join('');$('#status-filter').value=status;$('#subsystem-filter').setAttribute('aria-label',cots?'Filter by vendor':'Filter by subsystem');$('#status-filter').setAttribute('aria-label',cots?'Filter by order status':'Filter by stage');$('#subsystem-filter').innerHTML='<option value="">'+(cots?'All vendors':'All subsystems')+'</option>'+[...new Set(cots?state.cots.map(i=>vendorName(i.vendor)):state.parts.map(p=>p.subsystem).filter(Boolean))].sort().map(v=>'<option>'+escape(v)+'</option>').join('');$('#subsystem-filter').value=old;}
function switchView(next){
 view=['parts','board','cots','admin','todo'].includes(next)&&!(next==='admin'&&!isAdmin)&&!(next==='todo'&&isAdmin)?next:'parts';
 document.body.classList.toggle('production-view',view==='board');document.body.classList.toggle('register-view',view==='parts');
 document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
 $('#search').placeholder=view==='board'?'Search parts or students':view==='cots'?'Search parts or vendors':'Search parts';
 $('#search').value='';$('#status-filter').value='';$('#subsystem-filter').value='';$('#status-filter').hidden=view!=='cots';$('#tag-filter').hidden=true;$('#tag-filter').value='';refreshFilters();render();
}
const input=(name,label,type='text',value='',extra='')=>`<label ${name==='notes'||name==='name'?'class="full"':''}>${label}<input name="${name}" type="${type}" value="${escape(value)}" ${extra} maxlength="500"></label>`;
const select=(name,label,options,value)=>`<label>${label}<select name="${name}">${options.map(s=>`<option ${s===value?'selected':''}>${escape(s)}</option>`).join('')}</select></label>`;
function edit(id){if(!isAdmin){openWork(id);return;}if(view==='cots'){cotsController.edit(id);return;}editing=id||null;const record=state.parts.find(r=>r.id===id)||{};
 $('#dialog-title').textContent=id?'Edit part':'Add part';$('#delete-record').hidden=!id;
 $('#form-fields').innerHTML=input('name','Part name','text',record.name,'required')+input('number','Part number','text',record.number)+input('subsystem','Subsystem','text',record.subsystem)+input('quantity','Batch quantity','number',record.quantity??1,'min="1" step="1" required')+input('assignedTo','Assigned student (optional)','text',record.assignedTo,'list="student-options"')+select('status','Manufacturing stage',STATUSES,record.status||'Not Started')+select('priority','Priority',['Low','Normal','High'],record.priority||'Normal')+input('completedQty','Parts made','number',completedQuantity({...record,quantity:record.quantity||1})||0,'min="0" step="1" required')+input('material','Material','text',record.material)+'<label>Color<select name="color"><option value="">Not specified</option>'+PART_COLOR_PALETTE.map(c=>'<option value="'+c.value+'" '+(c.value===record.color?'selected':'')+'>'+c.label+'</option>').join('')+'</select></label>'+input('process','Manufacturing process','text',record.process)+input('due','Due date','date',record.due)+input('cad','Drawing / CAD link','url',record.cad)+
 '<fieldset class="full readiness-checklist"><legend>Ready to manufacture</legend><p id="readiness-message">The project manager confirms these checks before moving a part into cutting.</p>'+READINESS_CHECKS.map(([key,label])=>'<label><input type="checkbox" name="'+key+'" '+(record.readiness?.[key]?'checked':'')+'> '+escape(label)+'</label>').join('')+'</fieldset>'+`<label class="full blocked-field"><input name="blocked" type="checkbox" ${record.blocked?'checked':''}> <span>Blocked<small>Add the reason in shop notes.</small></span></label><label class="full">Shop notes<textarea name="notes" rows="3" maxlength="10000">${escape(record.notes||'')}</textarea></label>`+
 (record.history?.length?'<details class="full part-history"><summary>Recent activity</summary><ol>'+record.history.slice(-8).reverse().map(h=>'<li>'+escape(h.label)+'<small>'+escape(h.worker||'Team')+' · '+escape(new Date(h.at).toLocaleString())+'</small></li>').join('')+'</ol></details>':'');$('#form-fields').insertAdjacentHTML('beforeend',operationalFields({quantity:1,completedQty:0,...record},true,true));$('#form-fields').insertAdjacentHTML('beforeend','<datalist id="student-options">'+workspace.students.filter(s=>s.active).map(s=>'<option value="'+escape(s.name)+'">').join('')+'</datalist>');for(const key of ['process','material','subsystem']){const values=[...new Set(state.parts.map(p=>operationalKey(p[key])).filter(Boolean))].sort();$('#form-fields').insertAdjacentHTML('beforeend','<datalist id="'+key+'-options">'+values.map(v=>'<option value="'+escape(v)+'">').join('')+'</datalist>');$('#record-form').elements[key].setAttribute('list',key+'-options');}$('#record-dialog').showModal();
}
$('#form-fields').oninput=e=>{const affected={name:['drawingReviewed'],number:['drawingReviewed'],cad:['drawingReviewed'],material:['materialReady','setupReady'],quantity:['materialReady','setupReady'],process:['setupReady']}[e.target.name];for(const key of affected||[])$('#record-form').elements[key].checked=false;};
$('#record-form').addEventListener('submit',e=>{
 e.preventDefault();const values=Object.fromEntries(new FormData(e.target));Object.keys(values).forEach(k=>values[k]=values[k].trim());const previous=state.parts.find(p=>p.id===editing);
 const readiness=Object.fromEntries(READINESS_CHECKS.map(([k])=>[k,e.target.elements[k].checked]));for(const [key] of READINESS_CHECKS)delete values[key];
 let part={...previous,...values,id:editing||crypto.randomUUID(),quantity:Number(values.quantity),completedQty:Number(values.completedQty),readiness,blocked:e.target.elements.blocked.checked,owner:values.assignedTo||(previous?.assignedTo?'':previous?.owner||'')};
 try{part={...part,...readOperationalFields(e.target,part)};for(const k of ['subsystem','process','material']){const key=operationalKey(part[k]);part[k]=state.parts.map(p=>p[k]).find(v=>v?.toLowerCase()===key.toLowerCase())||key;}}catch(err){toast(err.message);return;}if(!validWorkspace({...state,parts:[part]})){toast('Check quantities, required fields and dates. Done pieces cannot exceed the batch.');return;}
 if(part.assignedTo&&!workspace.students.some(s=>s.active&&s.name===part.assignedTo)){toast('Choose an active student for the assignment.');return;}
 const changing=part.status!==(previous?.status||'Not Started');
 if(changing&&['Cutting','Finishing','Done'].includes(part.status)&&readinessIssues(part).length){$('#readiness-message').textContent=readinessIssues(part).join(' ');$('#readiness-message').className='cart-error';toast('Complete the readiness checks before advancing.');return;}
 if(part.status==='Done'&&!workspace.students.some(s=>s.active&&s.name===(part.assignedTo||part.owner))){toast('Assign an active student before marking Done.');return;}
 if(needsWorkerSelection(previous||{status:'Not Started',owner:''},part.status)||['Cutting','Finishing'].includes(part.status)&&!workspace.students.some(s=>s.active&&s.name===(part.assignedTo||part.owner))){editing=part.id;$('#record-dialog').close();beginWork(part,part.status);return;}
 try{part=changing?transitionPart({...part,status:previous?.status||'Not Started'},part.status):logPartChange(part,{},previous?'Part updated':'Part created');}catch(err){toast(err.message);return;}
 const next={...state,parts:previous?state.parts.map(p=>p.id===part.id?part:p):[...state.parts,part]};if(save(next)){$('#record-dialog').close();refreshFilters();render();toast('Part saved');}
});

function commitStartedPart(part,worker='',target='Cutting'){
 if(!isAdmin){toast('Only admins can move parts between stages.');return;}
 const student=workspace.students.find(s=>s.active&&s.name.toLowerCase()===(part.assignedTo||worker).trim().toLowerCase());if(!student){toast('Choose an active student. An admin can add students in Admin.');return;}worker=student.name;
 const current=state.parts.find(p=>p.id===part.id);
 // Avoid replacing a newer record if another tab changes it while the picker is open.
 if(pendingStart&&JSON.stringify(current)!==pendingStart.original){toast('This part changed in another tab. Open it again before starting.');$('#start-dialog').close();return;}
 try{const assigned=startPart(part,worker,target);const started=transitionPart({...assigned,status:current?.status||'Not Started'},target);const next={...state,parts:current?state.parts.map(p=>p.id===part.id?started:p):[...state.parts,started]};if(save(next)){pendingStart=null;$('#start-dialog').close();refreshFilters();render();toast(`Assigned to ${started.owner}`);}}catch(err){toast(err.message);}
}
function beginWork(part,target){
 if(!isAdmin)return;
 if(['Cutting','Finishing'].includes(target)&&readinessIssues(part).length){toast('Complete readiness checks before cutting.');openWork(part.id);return;}
 if(part.assignedTo?.trim()){commitStartedPart(part,'',target);return;}
 pendingStart={part,target,original:JSON.stringify(state.parts.find(p=>p.id===part.id))};
 $('#start-part-name').textContent=part.name;
 const names=workspace.students.filter(s=>s.active).map(s=>s.name).sort();
 $('#worker-choices').innerHTML=names.map(name=>`<button type="button" class="secondary" data-worker="${escape(name)}">${escape(name)}</button>`).join('');
 $('#worker-name').value='';$('#start-dialog').showModal();render();
}
function changeStatus(id,status){if(!isAdmin){toast('Only admins can move parts between stages.');render();return;}const part=state.parts.find(p=>p.id===id);if(!part||!STATUSES.includes(status))return;
 if(['Cutting','Finishing','Done'].includes(status)&&readinessIssues(part).length){openWork(id);$('#work-error').textContent=readinessIssues(part).join(' ');return;}
 if(['Cutting','Finishing','Done'].includes(status)&&!workspace.students.some(s=>s.active&&s.name===(part.assignedTo||part.owner))){if(status==='Done'){openWork(id);$('#work-error').textContent='Assign an active student in part details before marking Done.';}else beginWork({...part,assignedTo:''},status);return;}
 if(needsWorkerSelection(part,status)){beginWork(part,status);return;}
 try{const updated=transitionPart(part,status);if(save({...state,parts:state.parts.map(p=>p.id===id?updated:p)}))toast('Progress updated');}catch(err){toast(err.message);}render();}
$('#worker-choices').onclick=e=>{const button=e.target.closest('[data-worker]');if(button){$('#worker-name').value=button.dataset.worker;document.querySelectorAll('[data-worker]').forEach(b=>b.classList.toggle('selected',b===button));}};
$('#worker-name').oninput=()=>{document.querySelectorAll('[data-worker]').forEach(b=>b.classList.toggle('selected',b.dataset.worker===$('#worker-name').value));};
$('#start-form').onsubmit=e=>{e.preventDefault();if(pendingStart)commitStartedPart(pendingStart.part,$('#worker-name').value,pendingStart.target);};
['#cancel-start','#close-start'].forEach(s=>$(s).onclick=()=>$('#start-dialog').close());
$('#start-dialog').addEventListener('close',()=>{pendingStart=null;render();});
$('#delete-record').onclick=async()=>{if(!isAdmin)return;if(!await confirmAction('Remove this record? It can be recovered from Admin activity and recovery.'))return;const key=view==='inventory'?'materials':'parts';if(save({...state,[key]:state[key].filter(r=>r.id!==editing)})){$('#record-dialog').close();refreshFilters();render();toast('Record deleted');}};
$('#records').onclick=e=>{const sort=e.target.closest('[data-sort]');if(sort){const key=sort.dataset.sort;partSort={key,direction:partSort.key===key&&partSort.direction==='asc'?'desc':'asc'};render();return;}if(e.target.closest('[data-clear-filters]')){$('#search').value='';$('#status-filter').value='';$('#subsystem-filter').value='';$('#tag-filter').value='';render();return;}if(e.target.closest('[data-add-cots]')){cotsController.edit();return;}const finish=e.target.closest('[data-finish-piece]');if(finish){const part=state.parts.find(p=>p.id===finish.dataset.finishPiece);try{const updated=recordCompletion(part,Math.min(demand(part),completedQuantity(part)+1));if(save({...state,parts:state.parts.map(p=>p.id===part.id?updated:p)}))render();}catch(err){toast(err.message);}return;}const order=e.target.closest('[data-cots-order]'),received=e.target.closest('[data-cots-receive]');if(order||received){cotsController.quick((order||received).dataset[order?'cotsOrder':'cotsReceive'],Boolean(received));return;}const block=e.target.closest('[data-block]');if(block){openWork(block.dataset.block);return;}const advance=e.target.closest('[data-advance]');if(advance){if(advance.dataset.next==='Done')openWork(advance.dataset.advance);else changeStatus(advance.dataset.advance,advance.dataset.next);return;}const button=e.target.closest('[data-edit]');if(button){if(view==='cots')cotsController.edit(button.dataset.edit);else if(isAdmin&&view==='parts')edit(button.dataset.edit);else openWork(button.dataset.edit);}};
$('#records').onchange=e=>{if(e.target.dataset.status){changeStatus(e.target.dataset.status,e.target.value);}};
initBoardDrag({root:$('#records'),canMove:()=>!!shared?.ready&&isAdmin,getPart:id=>state.parts.find(p=>p.id===id),onUnavailable:()=>toast('Sign in and wait for the board to sync before moving parts.'),onMove:(id,status,original)=>{
 if(!shared?.ready||!isAdmin){toast('Wait for the board to sync before moving parts.');return;}
 const part=state.parts.find(p=>p.id===id);
 if(!part||JSON.stringify(part)!==original){toast('This part changed while you were dragging. Check it and try again.');return;}
 if(part.status===status)return;
 if(status==='Done'){
  if(part.status!=='Finishing'){toast('Move this part to Finishing before submitting finished work.');return;}
  openWork(id);return;
 }
 changeStatus(id,status);
}});

document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>switchView(b.dataset.view));
$('#add-record').onclick=()=>edit();['#close-dialog','#cancel-dialog'].forEach(s=>$(s).onclick=()=>$('#record-dialog').close());['#search','#status-filter','#tag-filter','#subsystem-filter'].forEach(s=>$(s).addEventListener('input',render));
function download(content,type,name){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#export').onclick=()=>{const kind=$('#csv-kind').value,keys=kind==='cots'?['name','vendor','number','needed','stock','ordered','received','status','eta','location','location2','url']:['name','number','subsystem','status','material','color','assignedTo','owner','due','quantity','completedQty'];download('﻿'+csv([keys,...state[kind].map(r=>keys.map(k=>kind==='cots'&&k==='status'?cotsStatus(r):r[k]))]),'text/csv;charset=utf-8',`7028-${kind}-${today()}.csv`);toast('CSV exported');};

try{$('#cleanup-backup').hidden=!localStorage.getItem(STORAGE_KEY+'-before-cleanup-v1');}catch{$('#cleanup-backup').hidden=true;}$('#cleanup-backup').onclick=()=>{const backup=localStorage.getItem(STORAGE_KEY+'-before-cleanup-v1');if(backup)download(backup,'application/json','7028-before-cleanup.json');};
$('#backup').onclick=()=>download(JSON.stringify(workspace,null,2),'application/json',`7028-workshop-${today()}.json`);
$('#restore').onclick=()=>{if(isAdmin)$('#import-file').click();};
$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5_000_000)throw Error('Backup must be under 5 MB.');const data=JSON.parse(await file.text());if(!validWorkspace(data))throw Error('This file is not a valid 7028 workspace backup.');localStorage.setItem('frc7028-before-restore',JSON.stringify(workspace));if(await confirmAction(`REPLACE all projects and records with this backup. IDs matching existing records are restored; records absent from the backup are removed and retained in recovery history. Preview: current ${workspace.parts.length} parts / ${workspace.cots.length} COTS; incoming ${data.parts.length} parts, ${data.materials.length} materials, and ${data.cots?.length||0} COTS items? A recovery copy has been saved on this device.`)&&saveWorkspace(normalizeAssignments(data),true)){refreshFilters();render();toast('Workspace restored');}}catch(err){toast(err instanceof SyntaxError?'The file is not valid JSON.':err.message);}e.target.value='';};
const cotsController=initCots({canManage:()=>isAdmin,canEdit:()=>accessRole!=='viewer',getWorkspace:()=>state,save,onChanged:()=>{refreshFilters();render();},toast});

$('#vendor-orders').onclick=e=>{const b=e.target.closest('[data-vendor-cart]');if(b)cotsController.cart(b.dataset.vendorCart);};

function emptyResults(){return '<div class="empty"><h3>'+((view==='cots'?state.cots:state.parts).length?'No matching records':'No records yet')+'</h3><p>Adjust the search or filters to continue.</p><button class="secondary" data-clear-filters>Clear filters</button></div>';}
function filtered(){return baseFiltered();}
function syncStatus(label,last){$('#sync-label').textContent=label;$('#save-status').textContent=label;$('#sync-panel').dataset.status=label;$('#sync-refresh').textContent=last?'Last successful refresh '+new Date(last).toLocaleTimeString([],{timeZone:'America/Chicago',hour:'numeric',minute:'2-digit',second:'2-digit'})+' CT':'';$('#sync-retry').hidden=label==='Saved'||label.startsWith('Saving');}
function showConflict(data,body){if(body.action==='restore'){const host=$('#conflict-form');host.innerHTML='<p>Team data changed after your restore preview. Replacing now removes records absent from this backup.</p><p>Current: '+data.workspace.parts.length+' parts / '+data.workspace.cots.length+' COTS. Backup: '+body.workspace.parts.length+' parts / '+body.workspace.cots.length+' COTS.</p><button class="primary">Replace with this backup</button>';host.onsubmit=async e=>{e.preventDefault();$('#conflict-dialog').close();await shared.resolve(body.workspace,data.workspace,data.revision,true);};$('#conflict-dialog').showModal();return;}const merged=mergeConcurrent(body.baseWorkspace,body.workspace,data.workspace),host=$('#conflict-form');host.innerHTML='<p>Your attempted changes are kept on this device. Choose each conflicting value. Other changes are retained automatically.</p>'+merged.conflicts.map((c,n)=>'<fieldset><legend>'+escape(c.name||c.id)+' · '+escape(c.field)+'</legend><p>Previously: '+escape(JSON.stringify(c.before))+'</p><label><input type="radio" name="conflict-'+n+'" value="remote" checked> Team value: '+escape(JSON.stringify(c.remote))+'</label><label><input type="radio" name="conflict-'+n+'" value="local"> My value: '+escape(JSON.stringify(c.local))+'</label></fieldset>').join('')+'<button class="primary">Apply chosen values</button>';host.onsubmit=async e=>{e.preventDefault();for(const [n,c] of merged.conflicts.entries()){const value=host.elements['conflict-'+n].value==='local'?c.local:c.remote;if(c.kind==='workspace')merged.workspace[c.field]=value;else if(c.field==='record')merged.workspace[c.kind]=[...merged.workspace[c.kind].filter(r=>r.id!==c.id),...(value?[value]:[])];else{const row=merged.workspace[c.kind].find(r=>r.id===c.id);if(row)row[c.field]=value;}}$('#conflict-dialog').close();await shared.resolve(merged.workspace,data.workspace,data.revision);};$('#conflict-dialog').showModal();}
$('#sync-retry').onclick=()=>shared.retry();

switchView('board');
shared=sharedWorkspace({getLocal:()=>workspace,onLoad:loadShared,onRole:(value,role,account)=>{identity=account;accessRole=role;isAdmin=value;document.body.dataset.role=role;refreshRecoveryButtons();$('#admin-tab').hidden=!value;$('#todo-tab').hidden=value;$('#restore').hidden=!value;$('#open-onshape').hidden=!value;$('#add-record').hidden=!value;refreshProjectPicker();},onStatus:syncStatus,onConflict:showConflict,onError:message=>{toast(message);refreshRecoveryButtons();}});

shared.start().then(()=>{if(isAdmin&&workspace.onshapeProjectId)initOnshape({enabled:()=>!!workspace.onshapeProjectId,getWorkspace:()=>projectScope(workspace,workspace.onshapeProjectId),save:next=>saveWorkspace(mergeProject(workspace,next,workspace.onshapeProjectId)),onChanged:()=>{refreshFilters();render();},toast});});
function updateShopTabs(){document.querySelectorAll('[data-shop-view]').forEach(b=>b.classList.toggle('selected',b.dataset.shopView===view));}
async function releaseWakeLock(){if(wakeLock){await wakeLock.release().catch(()=>{});wakeLock=null;}}
async function requestWakeLock(){if(!keepAwake||!shopMode||document.visibilityState!=='visible')return;try{if(!('wakeLock' in navigator))throw new Error('unsupported');wakeLock=await navigator.wakeLock.request('screen');wakeLock.addEventListener('release',()=>{wakeLock=null;$('#shop-awake').textContent=keepAwake?'Resume keep awake':'Keep awake';});$('#shop-awake').textContent='Display staying awake';}catch{keepAwake=false;$('#shop-awake').setAttribute('aria-pressed','false');$('#shop-awake').textContent='Keep awake';toast('Keep awake is unavailable. Use the smart board display settings.');}}
function setShopMode(enabled){if(enabled&&!shopMode)previousView=view;shopMode=enabled;document.body.classList.toggle('shop-mode',enabled);$('.shop-controls').hidden=!enabled;const url=new URL(location.href);if(enabled)url.searchParams.set('shop','1');else url.searchParams.delete('shop');history.replaceState(null,'',url);switchView(enabled?'board':previousView);updateShopTabs();if(!enabled){keepAwake=false;$('#shop-awake').setAttribute('aria-pressed','false');$('#shop-awake').textContent='Keep awake';releaseWakeLock();if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});}window.scrollTo(0,0);}
$('#enter-shop').onclick=()=>setShopMode(true);
$('#exit-shop').onclick=()=>setShopMode(false);
document.querySelectorAll('[data-shop-view]').forEach(b=>b.onclick=()=>{switchView(b.dataset.shopView);updateShopTabs();window.scrollTo(0,0);});
$('#shop-fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else throw new Error('unsupported');}catch{toast('Fullscreen is unavailable here. Open the app in the smart board browser and use its fullscreen control.');}};
document.addEventListener('fullscreenchange',()=>$('#shop-fullscreen').textContent=document.fullscreenElement?'Leave fullscreen':'Fullscreen');
$('#shop-awake').onclick=async()=>{keepAwake=!keepAwake;$('#shop-awake').setAttribute('aria-pressed',String(keepAwake));if(keepAwake)await requestWakeLock();else{await releaseWakeLock();$('#shop-awake').textContent='Keep awake';}};
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&keepAwake&&!wakeLock)requestWakeLock();});
let lastRenderedDate=today();
function updateClock(){if(today()!==lastRenderedDate){lastRenderedDate=today();render();}$('#shop-clock').textContent=new Date().toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});}
updateClock();setInterval(updateClock,15000);
if(new URLSearchParams(location.search).get('shop')==='1')setShopMode(true);
$('#sample-label').hidden=true;
$('#clear-workspace').hidden=!state.demo;
$('#clear-workspace').onclick=async()=>{if(await confirmAction('Clear all parts, materials, and COTS items from this device? Download a backup first.')){if(save({...state,demo:false,parts:[],materials:[],cots:[]})){$('#sample-label').hidden=true;$('#clear-workspace').hidden=true;refreshFilters();render();}}};

$('#home').onclick=e=>{e.preventDefault();switchView('parts');};
function specialView(title){$('#record-count').hidden=true;$('#page-title').textContent=title;$('#special-panel').hidden=false;$('.content-panel').hidden=true;$('#board-summary').hidden=true;$('#vendor-orders').hidden=true;$('#add-record').hidden=true;$('#result-count').textContent='';}
function renderAdmin(){
 specialView('Admin');if(!isAdmin){$('#special-panel').textContent='Admin access is required.';return;}
 // Keep real tool elements (and their listeners) while the Admin sections re-render.
 document.body.append($('#admin-tools'));
 $('#special-panel').innerHTML=`<section class="admin-section"><h2>Students</h2><form id="student-form" class="project-create"><label>Student name<input name="name" maxlength="100" required></label><label>Account email (optional)<input name="email" type="email" maxlength="254"></label><button class="primary">Add student</button></form><div class="admin-parts">${workspace.students.map(s=>`<div class="student-row"><strong>${escape(s.name)}${s.active?'':' (removed)'}<small>${escape(s.email||'No account linked')}</small></strong><button class="secondary" data-student-rename="${escape(s.id)}">Rename</button><button class="secondary" data-student-email="${escape(s.id)}">Link account</button><button class="secondary" data-student-toggle="${escape(s.id)}">${s.active?'Remove':'Restore'}</button></div>`).join('')}</div><p class="helper">Link a student’s sign-in email to show their assignments in Todo.</p></section>
 <section class="admin-section"><h2>Projects</h2><div class="admin-parts">${workspace.projects.map(p=>`<div class="student-row"><strong>${escape(p.name)} · ${p.year}${p.archived?' (removed)':''}</strong><button class="secondary" data-edit-project="${escape(p.id)}">Edit</button><button class="secondary" data-archive-project="${escape(p.id)}">${p.archived?'Restore':'Remove'}</button></div>`).join('')}</div><button class="secondary" data-new-project>New Project</button><label>BOM destination<select id="bom-project-setting"><option value="">Disconnected</option>${workspace.projects.filter(p=>!p.archived).map(p=>`<option value="${escape(p.id)}" ${p.id===workspace.onshapeProjectId?'selected':''}>${escape(p.name)} · ${p.year}</option>`).join('')}</select></label></section>
 <section class="admin-section" id="admin-tools-host"><h2>Tools and data</h2></section>
 <section class="admin-section"><h2>Activity and recovery</h2><details><summary>Recent team activity</summary>${[...(workspace.auditLog||[])].slice(-100).reverse().map(a=>`<details><summary>${escape(a.name)} · ${escape(a.actor)} · ${escape(a.at)}</summary><pre>${escape(JSON.stringify(a.changes,null,2))}</pre></details>`).join('')}</details><details><summary>Removed records</summary>${(workspace.recordTombstones||[]).map((t,n)=>`<p>${escape(t.record.name)} <button class="secondary" data-recover-id="${n}">Restore record</button></p>`).join('')}</details></section>`;
 $('#admin-tools-host').append($('#admin-tools'));$('#admin-tools').hidden=false;
 $('#student-form').onsubmit=e=>{e.preventDefault();const name=e.target.elements.name.value.trim(),email=e.target.elements.email.value.trim().toLowerCase();if(workspace.students.some(s=>s.name.toLowerCase()===name.toLowerCase()||email&&s.email===email)){toast('This student or account already exists.');return;}if(saveWorkspace({...workspace,students:[...workspace.students,{id:crypto.randomUUID(),name,email,active:true}]}))renderAdmin();};
 $('#bom-project-setting').onchange=e=>{if(saveWorkspace({...workspace,onshapeProjectId:e.target.value}))toast('BOM destination updated');};
}
$('#special-panel').onclick=async e=>{
 const task=e.target.closest('[data-task]');if(task){const p=workspace.parts.find(p=>p.id===task.dataset.task);chooseProject(p.projectId);openWork(p.id);return;}
 if(!isAdmin)return;const target=e.target.closest('button');if(!target)return;const d=target.dataset;
 if('newProject'in d){openProject();return;}
 if(d.editProject){openProject(d.editProject);return;}
 if(d.recoverId!==undefined){const t=workspace.recordTombstones?.[Number(d.recoverId)];if(t&&!workspace[t.kind].some(p=>p.id===t.record.id)&&saveWorkspace(normalizeAssignments({...workspace,[t.kind]:[...workspace[t.kind],t.record]})))render();return;}
 if(d.studentEmail){const s=workspace.students.find(s=>s.id===d.studentEmail),email=(await askText('Student account email (leave blank to unlink)',s.email||''))?.trim().toLowerCase();if(email===undefined)return;if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){toast('Enter a valid email.');return;}if(email&&workspace.students.some(x=>x.id!==s.id&&x.email===email)){toast('That account is already linked.');return;}if(saveWorkspace({...workspace,students:workspace.students.map(x=>x.id===s.id?{...x,email}:x)}))render();return;}
 if(d.studentRename){const s=workspace.students.find(s=>s.id===d.studentRename),name=(await askText('Student name',s.name))?.trim();if(name&&saveWorkspace({...workspace,students:workspace.students.map(x=>x.id===s.id?{...x,name}:x),parts:workspace.parts.map(p=>({...p,owner:p.owner===s.name?name:p.owner,assignedTo:p.assignedTo===s.name?name:p.assignedTo}))}))render();return;}
 if(d.studentToggle){const s=workspace.students.find(s=>s.id===d.studentToggle);if(saveWorkspace({...workspace,students:workspace.students.map(x=>x.id===s.id?{...x,active:!x.active}:x),parts:workspace.parts.map(p=>s.active&&p.status!=='Done'&&p.assignedTo===s.name?{...p,assignedTo:''}:p)}))render();return;}
 if(d.archiveProject){const p=workspace.projects.find(p=>p.id===d.archiveProject);if(!p.archived&&(p.id===workspace.onshapeProjectId||workspace.projects.filter(x=>!x.archived).length===1)){toast('Keep an active project and disconnect the BOM before removing its project.');return;}if(saveWorkspace({...workspace,projects:workspace.projects.map(x=>x.id===p.id?{...x,archived:!x.archived}:x)})){if(p.id===activeProject)chooseProject(workspace.projects.find(x=>!x.archived).id);refreshProjectPicker();render();}}
};
let editingProject=null;
function openProject(id){if(!isAdmin)return;editingProject=id||null;const p=workspace.projects.find(x=>x.id===id);$('#project-title').textContent=p?'Edit project':'New Project';$('#project-form').elements.name.value=p?.name||'';$('#project-form').elements.year.value=p?.year||new Date().getFullYear();$('#project-error').textContent='';$('#project-dialog').showModal();}
for(const id of ['close-project','cancel-project'])$('#'+id).onclick=()=>$('#project-dialog').close();
$('#project-form').onsubmit=e=>{e.preventDefault();if(!isAdmin)return;const name=e.target.elements.name.value.trim(),year=Number(e.target.elements.year.value);if(!name||!Number.isInteger(year)||year<2000||year>2100)return;if(workspace.projects.some(p=>p.id!==editingProject&&p.name.toLowerCase()===name.toLowerCase())){$('#project-error').textContent='That project name already exists.';return;}const id=editingProject||crypto.randomUUID(),projects=editingProject?workspace.projects.map(p=>p.id===id?{...p,name,year}:p):[...workspace.projects,{id,name,year,archived:false}];if(saveWorkspace({...workspace,projects})){$('#project-dialog').close();chooseProject(id);refreshProjectPicker();render();}};
$('#dashboard-picker').onchange=e=>{dashboard=DASHBOARDS.includes(e.target.value)?e.target.value:'Manufacturing';if(shopMode&&dashboard!=='Manufacturing')setShopMode(false);render();};

function openWork(id){const p=state.parts.find(p=>p.id===id);if(!p)return;workPart=id;workOriginal=JSON.stringify(p);$('#work-title').textContent=(p.number?p.number+' · ':'')+p.name;$('#work-error').textContent='';$('#work-details').hidden=!isAdmin;const index=STATUSES.indexOf(p.status),next=STATUSES[index+1];$('#work-next').hidden=!isAdmin||!next;$('#work-next').textContent=next==='Done'?'Mark Done':next?'Start '+next.toLowerCase():'';$('#work-fields').innerHTML='<p class="work-meta">'+escape(p.number)+' · '+escape(p.status)+' · '+escape(p.owner||p.assignedTo||'Unassigned')+'</p><p>'+escape(p.material||'Material needs admin setup')+' · '+escape(p.process||'Process needs admin setup')+'</p>'+((p.cad&&/^https?:\/\//.test(p.cad))?'<a class="drawing-link" href="'+escape(p.cad)+'" target="_blank" rel="noopener noreferrer">Open drawing</a>':'')+'<fieldset class="readiness-checklist"><legend>Ready to manufacture</legend>'+READINESS_CHECKS.map(([key,label])=>'<label><input name="'+key+'" type="checkbox" '+(p.readiness?.[key]?'checked':'')+'> '+escape(label)+'</label>').join('')+'</fieldset>'+(p.status==='Finishing'?'<label class="worker-name-label">Parts made<input type="number" name="finished" min="0" max="'+demand(p)+'" step="1" value="'+completedQuantity(p)+'"></label>':'')+'<label class="work-block"><input type="checkbox" name="blocked" '+(p.blocked?'checked':'')+'> Blocked</label><label>Blocker / return reason<textarea name="blockReason" maxlength="2000">'+escape(p.blockReason||'')+'</textarea></label><label>Shop notes<textarea name="notes" maxlength="10000">'+escape(p.notes||'')+'</textarea></label>';$('#work-fields').insertAdjacentHTML('beforeend',operationalFields(p,isAdmin));for(const el of $('#work-form').querySelectorAll('input,textarea,button[type=submit]'))el.disabled=accessRole==='viewer';$('#work-dialog').showModal();}
$('#close-work').onclick=()=>$('#work-dialog').close();$('#work-details').onclick=()=>{const id=workPart;$('#work-dialog').close();if(isAdmin)edit(id);};$('#work-form').onsubmit=e=>{e.preventDefault();const current=state.parts.find(p=>p.id===workPart);if(!current||JSON.stringify(current)!==workOriginal){$('#work-error').textContent='This part changed. Close and reopen it before saving.';return;}const form=e.target,blocked=form.elements.blocked.checked,blockReason=form.elements.blockReason.value.trim();if(blocked&&!blockReason){$('#work-error').textContent='Add a reason so the next person knows what is blocking the job.';return;}let part=logPartChange(current,{readiness:Object.fromEntries(READINESS_CHECKS.map(([key])=>[key,form.elements[key].checked])),blocked,blockReason,notes:form.elements.notes.value.trim()},'Shop progress updated');try{part={...part,...readOperationalFields(form,part)};if(form.elements.finished&&Number(form.elements.finished.value)!==completedQuantity(current))part=recordCompletion(part,Number(form.elements.finished.value));if(e.submitter?.value==='next'){if(!isAdmin)throw Error('Only admins can move parts between stages.');const next=STATUSES[STATUSES.indexOf(part.status)+1];if(!next)return;if(['Cutting','Finishing','Done'].includes(next)&&readinessIssues(part).length)throw Error(readinessIssues(part).join(' '));if(next==='Done'&&!workspace.students.some(s=>s.active&&s.name===(part.assignedTo||part.owner)))throw Error('Assign an active student in part details before marking Done.');if(needsWorkerSelection(part,next)||(!part.assignedTo&&!workspace.students.some(s=>s.active&&s.name===part.owner))){ $('#work-dialog').close();beginWork(part,next);return;}part=transitionPart(part,next);}if(save({...state,parts:state.parts.map(p=>p.id===part.id?part:p)})){$('#work-dialog').close();render();toast(part.status==='Done'?'Part marked Done':'Progress saved');}}catch(err){$('#work-error').textContent=err.message;}};
function projectChanged(e){const id=e.target.value;if(id==='__new__'){e.target.value=activeProject;openProject();}else chooseProject(id);}
$('#project-picker').onchange=projectChanged;$('#shop-project-picker').onchange=projectChanged;refreshProjectPicker();

function refreshRecoveryButtons(){try{$('#migration-backup').hidden=!localStorage.getItem('frc7028-before-shared-migration');$('#unsynced-backup').hidden=!localStorage.getItem('frc7028-unsynced-backup');}catch{}}
$('#migration-backup').onclick=()=>download(localStorage.getItem('frc7028-before-shared-migration'),'application/json','7028-before-shared-sync.json');$('#unsynced-backup').onclick=()=>download(localStorage.getItem('frc7028-unsynced-backup'),'application/json','7028-unsynced-changes.json');refreshRecoveryButtons();
